import { Injectable } from '@angular/core';
import { environment } from '../../environments/environment';

declare let gtag: Function;

@Injectable({
  providedIn: 'root'
})
export class GoogleAnalyticsService {
  
  constructor() {
    this.initializeGoogleAnalytics();
  }

  private initializeGoogleAnalytics(): void {
    if (environment.googleAnalytics?.trackingId) {
      // Dynamically load the Google Analytics script
      const script = document.createElement('script');
      script.async = true;
      script.src = `https://www.googletagmanager.com/gtag/js?id=${environment.googleAnalytics.trackingId}`;
      document.head.appendChild(script);
      
      // Configure Google Analytics
      gtag('config', environment.googleAnalytics.trackingId);
    }
  }

  // Track page views
  trackPageView(pageTitle: string, pagePath: string): void {
    if (environment.googleAnalytics?.trackingId) {
      gtag('event', 'page_view', {
        page_title: pageTitle,
        page_location: window.location.href,
        page_path: pagePath
      });
    }
  }

  // Track custom events
  trackEvent(eventName: string, eventCategory: string, eventLabel?: string): void {
    if (environment.googleAnalytics?.trackingId) {
      gtag('event', eventName, {
        event_category: eventCategory,
        event_label: eventLabel
      });
    }
  }

  // Track form submissions
  trackFormSubmission(formName: string): void {
    this.trackEvent('form_submit', 'Contact', formName);
  }
}
